import { useAuthenticator } from '@aws-amplify/ui-react';
import { Navigate } from 'react-router-dom';
import { ArrowLeft, Heart } from 'lucide-react';

const MedicalAssistant = () => {
  const { user } = useAuthenticator();

  if (!user) {
    return <Navigate to="/login" replace />;
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-green-50 to-emerald-100">
      {/* Header */}
      <div className="bg-white shadow-sm border-b border-gray-200">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <div className="flex items-center gap-4">
              <button
                onClick={() => window.history.back()}
                className="p-2 text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-lg transition-colors"
              >
                <ArrowLeft className="w-5 h-5" />
              </button>
              <div className="flex items-center gap-3">
                <div className="p-2 bg-green-100 rounded-lg">
                  <Heart className="w-6 h-6 text-green-600" />
                </div>
                <div>
                  <h1 className="text-xl font-semibold text-gray-900">Medical Assistant</h1>
                  <p className="text-sm text-gray-500">AI-powered medical assistant for healthcare professionals</p>
                </div>
              </div>
            </div>
            <div className="text-sm text-gray-500">
              Welcome, {user?.attributes?.email || user?.username}
            </div>
          </div>
        </div>
      </div>

      {/* Embedded Medical Assistant */}
      <div className="h-[calc(100vh-64px)]">
        <iframe
          src="https://medicalassistant.operisoft.com/rainbow"
          className="w-full h-full border-0"
          title="Medical Assistant"
          allow="camera; microphone; geolocation; encrypted-media"
          sandbox="allow-same-origin allow-scripts allow-forms allow-popups allow-popups-to-escape-sandbox"
        />
      </div>
    </div>
  );
};

export default MedicalAssistant;